import os
out = ["-- خمسة مشاريع نموذجية أسبوعية وشهرية (مسودة، reviewed=false): تُراجع ثم تُنشر من لوحة المشرف ومركز الجودة"]
for x in L:
    cols = "slug,kind,cat,type,title,icon,levels,subject,skill,difficulty,descr,instr,minutes,span,data,link,reviewed,status,sort_order"
    lv = "array[" + ",".join("'%s'" % v for v in x["levels"]) + "]::text[]"
    q = lambda v: "'" + str(v).replace("'", "''") + "'"
    out.append("insert into public.proj_items(%s) values (%s,'project',%s,'project',%s,%s,%s,%s,%s,%s,%s,%s,%d,%s,$j$%s$j$::jsonb,'{}'::jsonb,false,'draft',%d) on conflict (slug) do nothing;" % (
        cols, q(x["slug"]), q(x["cat"]), q(x["title"]), q(x["icon"]), lv, q(x["subject"]), q(x["skill"]), q(x["difficulty"]), q(x["descr"]), q(x["instr"]), x["minutes"], q(x["span"]), json.dumps(x["data"], ensure_ascii=False), x["sort_order"]))
open(os.path.join(os.path.dirname(__file__), "proj2_examples.sql"), "w", encoding="utf8").write("\n".join(out) + "\n")
json.dump(L, open("/tmp/pj2/examples.json", "w", encoding="utf8"), ensure_ascii=False)
